{
  "extracted_concepts": [
    {
      "name": "内积",
      "aliases": ["inner product", "内积符号"],
      "definition_snippet": "在实向量空间 V 上定义的二元运算 ⟨α, β⟩，满足对称性、线性性、正定性。",
      "category": "concept"
    },
    {
      "name": "对称性",
      "aliases": ["symmetry", "内积对称性"],
      "definition_snippet": "⟨α, β⟩ = ⟨β, α⟩。",
      "category": "property"
    },
    {
      "name": "线性性",
      "aliases": ["linearity", "内积线性性"],
      "definition_snippet": "⟨kα + lβ, γ⟩ = k⟨α, γ⟩ + l⟨β, γ⟩。",
      "category": "property"
    },
    {
      "name": "正定性",
      "aliases": ["positive definiteness", "内积正定性"],
      "definition_snippet": "⟨α, α⟩ ≥ 0，且等号成立当且仅当 α = 0。",
      "category": "property"
    },
    {
      "name": "实向量空间",
      "aliases": ["real vector space", "实线性空间"],
      "definition_snippet": "定义内积所依托的向量空间 V。",
      "category": "concept"
    },
    {
      "name": "向量空间",
      "aliases": ["vector space", "线性空间"],
      "definition_snippet": "向量及其加法、数乘运算构成的代数结构。",
      "category": "concept"
    },
    {
      "name": "内积空间",
      "aliases": ["inner product space", "欧几里得空间"],
      "definition_snippet": "定义了内积的向量空间称为内积空间。",
      "category": "concept"
    },
    {
      "name": "范数",
      "aliases": ["norm", "向量长度"],
      "definition_snippet": "‖α‖ = √⟨α, α⟩。",
      "category": "concept"
    },
    {
      "name": "距离",
      "aliases": ["distance", "向量距离"],
      "definition_snippet": "d(α, β) = ‖α - β‖。",
      "category": "concept"
    },
    {
      "name": "正交",
      "aliases": ["orthogonality", "垂直"],
      "definition_snippet": "若 ⟨α, β⟩ = 0，则称 α 与 β 正交。",
      "category": "concept"
    },
    {
      "name": "标准正交基",
      "aliases": ["orthonormal basis", "标准正交基底"],
      "definition_snippet": "两两正交且每个向量都是单位向量的基。",
      "category": "concept"
    },
    {
      "name": "单位向量",
      "aliases": ["unit vector", "长度为1的向量"],
      "definition_snippet": "范数等于 1 的向量。",
      "category": "concept"
    },
    {
      "name": "基",
      "aliases": ["basis", "基底"],
      "definition_snippet": "向量空间中一组线性无关且能生成整个空间的向量组。",
      "category": "concept"
    },
    {
      "name": "Gram-Schmidt 正交化",
      "aliases": ["Gram-Schmidt process", "格拉姆-施密特正交化"],
      "definition_snippet": "将任意基转化为标准正交基的过程。",
      "category": "operation"
    },
    {
      "name": "正交投影",
      "aliases": ["orthogonal projection", "投影"],
      "definition_snippet": "Proj_W α = Σ⟨α, eᵢ⟩eᵢ，向量 α 在子空间 W 上的投影。",
      "category": "operation"
    },
    {
      "name": "子空间",
      "aliases": ["subspace", "向量子空间"],
      "definition_snippet": "向量空间中满足加法和数乘封闭性的子集。",
      "category": "concept"
    },
    {
      "name": "最小二乘法",
      "aliases": ["least squares method", "最小平方方法"],
      "definition_snippet": "当 Ax = b 无解时，求 x 使 ‖Ax - b‖ 最小。",
      "category": "operation"
    },
    {
      "name": "正规方程",
      "aliases": ["normal equation", "法方程"],
      "definition_snippet": "x̂ = (A^T A)⁻¹ A^T b 给出的最小二乘解方程。",
      "category": "theorem"
    },
    {
      "name": "列空间",
      "aliases": ["column space", "矩阵列空间"],
      "definition_snippet": "矩阵 A 的列向量张成的子空间。",
      "category": "concept"
    },
    {
      "name": "线性方程组",
      "aliases": ["linear system", "Ax=b"],
      "definition_snippet": "形如 Ax = b 的方程组。",
      "category": "concept"
    },
    {
      "name": "残差范数",
      "aliases": ["residual norm", "误差范数"],
      "definition_snippet": "‖Ax - b‖，最小二乘法中最小化的目标量。",
      "category": "concept"
    }
  ],
